window.kbPageData["views/entry/k-aa052a4589f73e60"] = {"key":"entry/k-aa052a4589f73e60","state":{"route":"entry/k-aa052a4589f73e60"},"node":{"id":"k-aa052a4589f73e60","mode":"k","title":"共同富裕","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["全体人民共同富裕"],"qs":["政治理论必刷100题#47","国考 2023 地市级 行测#5","江苏 2024 C类 行测#5"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":3,"tags":{"专题":["modern"],"主类":["概念与词义"],"出处性质":["专项题干","机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"共同富裕是全体人民逐步实现物质生活和精神生活都富裕的发展目标，也是中国式现代化的重要特征。","review":{"title":"共同富裕","type":"概念与词义","definition":"共同富裕是全体人民逐步实现物质生活和精神生活都富裕的发展目标，也是中国式现代化的重要特征。","explanation":"共同富裕面向全体人民，需要在高质量发展中循序渐进地推进。各地可以因地制宜探索路径，全国目标从全局统筹。推进过程中要兼顾效率和公平，使初次分配、再分配、三次分配协调配套。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"中国式现代化的中国特色"}],"related":["k-a00a8fcb9d224472","k-abc7a40f1ee48790","k-bea39803d34d2724"],"examFocus":{"政治理论必刷100题#47":"对照“十五五”经济社会发展座谈会讲话，区分发展规划的民生取向、经济布局和地区规划要求。","国考 2023 地市级 行测#5":"核对共同富裕的覆盖范围、地方探索与总体目标的关系，以及增长和分配的安排。","江苏 2024 C类 行测#5":"比较“千万工程”的实践范围与各项表述所称成效的覆盖范围，核对其对生态、农村发展和城乡融合的作用。"}},"aspects":[{"title":"“十五五”规划谋划中的民生要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。C符合2025年4月30日部分省区市“十五五”时期经济社会发展座谈会讲话，将造福人民、在发展中保障和改善民生与稳步推动共同富裕联系起来。本题选A，错误在于把“基本实现社会主义现代化”写成了“全面实现社会主义现代化”。","evidence":"把造福人民作为根本价值取向，坚持在发展中保障和改善民生，稳步推动共同富裕","qids":["政治理论必刷100题#47"]}]},{"title":"共同富裕的内涵与实现路径","uses":[{"unit":"Q2","role":"直接考查","use":"本题选C。①涵盖全体人民的物质生活和精神生活，③强调三次分配协调配套，④把共同奋斗促进增长与合理制度安排改善分配联系起来。②前半句的因地制宜有题据支持，错误在于主张城乡和各区域各自确定共同富裕指标。","evidence":"各提各的指标，要从全局上来看。","qids":["国考 2023 地市级 行测#5"]}]},{"title":"地方工程成效与全国目标","uses":[{"unit":"Q3","role":"解题依据","use":"本题选C。题中的浙江“千万工程”通过改善人居环境、发展生产等促进农民富裕。②把这一地方实践的成效写成已经实现全体人民共同富裕，超出了题据支持的范围，因此正确组合为①③④。","evidence":"②实现了全体人民共同富裕的奋斗目标","qids":["江苏 2024 C类 行测#5"]}]}],"sources":[{"id":"c1c181c77df0cdd7","label":"全体人民共同富裕","topic":"发展与治理","category":"非时政","text":"1.全体人民共同富裕\n党的二十大报告指出，到二〇三五年，全体人民共同富裕取得更为明显的实质性进展。\n全体人民共同富裕是一个总体概念，它不是也不可能是所有人都同时富裕，不同人群不\n仅实现富裕的程度有高有低，时间上也会有先有后；它不是也不可能是所有地区同时达到一\n个富裕水准，不同地区富裕程度还会存在一定差异，而不是齐头并进。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":18,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#47":{"paper":"政治理论必刷100题","n":47,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",14],"asrc":["国省考政治理论必刷100题.pdf",61],"card":"0d22e74f10d21a4306d29542","links":[{"id":"k-aa052a4589f73e60","role":"直接考查","why":"考查“十五五”时期发展规划的价值取向及共同富裕要求。"}]},"国考 2023 地市级 行测#5":{"paper":"国考 2023 地市级 行测","n":5,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",1],"asrc":["f3ab652d8e31c5bbdabc.pdf",2],"card":"62e6c598bc157bb0c0fe57d0","links":[{"id":"k-aa052a4589f73e60","role":"直接考查","why":"该表述明确了共同富裕的覆盖对象和物质、精神两个方面。"}]},"江苏 2024 C类 行测#5":{"paper":"江苏 2024 C类 行测","n":5,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",1],"asrc":["02d6b49839583bdaf297.pdf",2],"card":"98551fe75e468e8d61347276","links":[{"id":"k-aa052a4589f73e60","role":"解题依据","why":"共同富裕是长期目标，判断工程成效时须区分促进农民富裕与全国性目标的实现程度。"}]}},"terms":{"k-a00a8fcb9d224472":{"id":"k-a00a8fcb9d224472","mode":"k","type":"制度与规则","title":"收入分配制度","qs":[],"count":4},"k-abc7a40f1ee48790":{"id":"k-abc7a40f1ee48790","mode":"k","type":"观点与论证","title":"全体人民共同富裕的现代化","qs":[],"count":2},"k-bea39803d34d2724":{"id":"k-bea39803d34d2724","mode":"k","type":"观点与论证","title":"物质文明和精神文明相协调","qs":[],"count":3}},"references":{"twenty":{"name":"党的二十大报告（2022年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2022/art_d664717b51f54b9886bc371c5f3594ed.html"}},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-aa052a4589f73e60":[["政治理论必刷100题#47"],["国考 2023 地市级 行测#5"],["江苏 2024 C类 行测#5"]]}};
